description:
Design a signed magnitude comparator that determines whether `num1` is greater than `num2`. The module processes the two signed 16-bit inputs in stages: first, it captures the inputs; next, it computes the difference between the two numbers while initializing a secondary operand; then it checks the sign of the result to establish the comparison outcome. Finally, the output reflects whether `num1` is greater than `num2`, with a logic HIGH indicating that `num1` is greater.
module top_module(
    input signed [15:0] num1,
    input signed [15:0] num2,
    output reg out
);

code:
module top_module(
    input signed [15:0] num1,
    input signed [15:0] num2,
    output reg out
);reg signed [15:0] stage1_num1, stage1_num2;
reg signed [15:0] stage2_num1, stage2_num2;
reg signed [15:0] stage3_num1, stage3_num2;

always @(num1, num2) begin
    stage1_num1 <= num1;
    stage1_num2 <= num2;
end

always @(stage1_num1, stage1_num2) begin
    stage2_num1 <= stage1_num1 - stage1_num2;
    stage2_num2 <= 0;
end

always @(stage2_num1, stage2_num2) begin
    stage3_num1 <= stage2_num1;
    stage3_num2 <= stage2_num2 - stage2_num1[15];
end

always @(stage3_num2) begin
    out <= ~stage3_num2[15];
end

endmodule

