description:
Design a 3-to-4 line decoder that takes a 3-bit input extracted from the upper bits of a 9-bit control signal. Depending on the value of these control bits, the circuit generates a specific 4-bit output, `td_mode`, based on a defined mapping. Each possible 3-bit input corresponds to a unique 4-bit output, allowing for a straightforward selection mechanism to control modes in a video system CPU. If the input does not match any defined case, the output defaults to `0000`.
module top_module(
    // inputs:
    ctrl,

    // outputs:
    td_mode
);

code:
module top_module(
    // inputs:
    ctrl,

    // outputs:
    td_mode
);output [3:0] td_mode;
    input [8:0] ctrl;

    wire [2:0] ctrl_bits_for_mux;
    reg [3:0] td_mode;
    assign ctrl_bits_for_mux = ctrl[7:5];

    always @*
    begin
        case (ctrl_bits_for_mux)
            3'b000: td_mode = 4'b0000;
            3'b001: td_mode = 4'b1000;
            3'b010: td_mode = 4'b0100;
            3'b011: td_mode = 4'b1100;
            3'b100: td_mode = 4'b0010;
            3'b101: td_mode = 4'b1010;
            3'b110: td_mode = 4'b0101;
            3'b111: td_mode = 4'b1111;
            default: td_mode = 4'b0000;
        endcase
    end

endmodule

