description:
Design a 4-bit multiplier that computes the product of two 4-bit inputs, producing an 8-bit output. The module employs a sequential approach, where intermediate results of partial products are calculated based on the individual bits of the second input, shifting them appropriately and accumulating the results. The final output includes a parity bit as the most significant bit, ensuring the output is both the product and includes correctness verification.
module top_module(
    input [3:0] in_0,
    input [3:0] in_1,
    output reg [7:0] out
);

code:
module top_module(
    input [3:0] in_0,
    input [3:0] in_1,
    output reg [7:0] out
);reg [3:0] stage_1_out;
reg [3:0] stage_2_out;
reg [3:0] stage_3_out;
reg [3:0] stage_4_out;

always @(*) begin
    stage_1_out = in_0 * in_1[0];
end

always @(*) begin
    stage_2_out = {stage_1_out[2:0], 1'b0} + (in_0 * in_1[1]);
end

always @(*) begin
    stage_3_out = {stage_2_out[3:0], 2'b00} + (in_0 * in_1[2]);
end

always @(*) begin
    stage_4_out = {stage_3_out[3:0], 3'b000} + (in_0 * in_1[3]);
end

always @(*) begin
    out = {stage_4_out, 1'b0};
    out[7] = ^out[6:0];
end

endmodule

