		k <= {s1, 32'd0} + {k11, 7'd0} + {s1, 6'd0} + {s1, 4'd0} + s1;

		if (reset)
		begin
			cnt <= 0;
			tx_done <= 1'b0;

			s <= rx_a[255:0];
		end
	end

